local QuillTrimmerMaker = {}
local PRODUCTS = {
    iron_quilltrimmer = { name = "Železni strižnik peres", ironCost = 3, woodCost = 2, leatherCost = 1, time = 5, cost = 150, prestige = 4, happiness = 2, description = "Železni strižnik peres za pisarje." },
    bronze_quilltrimmer = { name = "Bronast strižnik peres", bronzeCost = 3, ironCost = 1, woodCost = 2, leatherCost = 1, time = 7, cost = 365, prestige = 6, happiness = 3, description = "Bronast strižnik peres za pisarje." },
    silver_quilltrimmer = { name = "Srebrn strižnik peres", silverCost = 3, bronzeCost = 1, ironCost = 1, woodCost = 2, leatherCost = 1, time = 11, cost = 880, prestige = 11, happiness = 4, description = "Srebrn strižnik peres za pisarje." },
    gilded_quilltrimmer = { name = "Pozlačen strižnik peres", goldCost = 1, silverCost = 3, bronzeCost = 1, woodCost = 2, leatherCost = 1, time = 15, cost = 1900, prestige = 20, happiness = 5, description = "Pozlačen strižnik peres za pisarje." },
    jewel_set_quilltrimmer = { name = "Draguljast strižnik peres", goldCost = 2, silverCost = 3, jewelCost = 1, bronzeCost = 1, woodCost = 2, leatherCost = 1, time = 19, cost = 4100, prestige = 36, happiness = 7, description = "Draguljast strižnik peres za pisarje." },
    royal_sovereign_quilltrimmer = { name = "Kraljevski suveren strižnik peres", goldCost = 3, silverCost = 3, jewelCost = 2, pearlCost = 2, bronzeCost = 1, woodCost = 3, leatherCost = 1, time = 26, cost = 8800, prestige = 68, happiness = 13, description = "Suveren strižnik peres z biseri za krono." },
}
local BUILDINGS = {
    quilltrimmer_workshop = { name = "Quilltrimmer delavnica", cost = { gold = 325, wood = 185, stone = 130, iron = 7 }, upkeep = 6, qualityBonus = 5 },
    quilltrimmer_house = { name = "Quilltrimmer hiša", cost = { gold = 1185, wood = 370, stone = 265, silver = 7, iron = 7 }, upkeep = 25, qualityBonus = 18 },
    master_quilltrimmer_atelier = { name = "Mojstrski quilltrimmer atelje", cost = { gold = 2975, wood = 425, stone = 515, silver = 35, gold = 7 }, upkeep = 70, qualityBonus = 30 },
    sovereign_quilltrimmer_palace = { name = "Suverena quilltrimmer palača", cost = { gold = 12920, wood = 650, stone = 825, gold = 83, jewel = 19 }, upkeep = 253, qualityBonus = 55, prestigeBonus = 50 },
}
QuillTrimmerMaker.ironStock=16; QuillTrimmerMaker.bronzeStock=12; QuillTrimmerMaker.woodStock=10; QuillTrimmerMaker.leatherStock=8; QuillTrimmerMaker.silverStock=8; QuillTrimmerMaker.goldStock=6; QuillTrimmerMaker.jewelStock=4; QuillTrimmerMaker.pearlStock=4
QuillTrimmerMaker.productStock = {}; QuillTrimmerMaker.buildings = {}; QuillTrimmerMaker.maker = nil; QuillTrimmerMaker.activeMaking = {}; QuillTrimmerMaker.totalProducts = 0; QuillTrimmerMaker.dayTimer = 0
function QuillTrimmerMaker.init() QuillTrimmerMaker.ironStock=16; QuillTrimmerMaker.bronzeStock=12; QuillTrimmerMaker.woodStock=10; QuillTrimmerMaker.leatherStock=8; QuillTrimmerMaker.silverStock=8; QuillTrimmerMaker.goldStock=6; QuillTrimmerMaker.jewelStock=4; QuillTrimmerMaker.pearlStock=4; QuillTrimmerMaker.productStock={}; QuillTrimmerMaker.buildings={}; QuillTrimmerMaker.maker=nil; QuillTrimmerMaker.activeMaking={}; QuillTrimmerMaker.totalProducts=0; QuillTrimmerMaker.dayTimer=0; print("[QuillTrimmerMaker] Royal Quill Trimmer Maker System initialized (6 products, 4 buildings)") end
function QuillTrimmerMaker.hireMaker(n,s) s=s or math.random(55,90); local c=580+s*12; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; QuillTrimmerMaker.maker={name=n or ("Strižnik "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Strižnik najet: %s (spretnost: %d)",QuillTrimmerMaker.maker.name,s),"success") end; return true end
function QuillTrimmerMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function QuillTrimmerMaker.build(id) local ok,e=QuillTrimmerMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(QuillTrimmerMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function QuillTrimmerMaker.getQualityBonus() local b=0; for _,bd in ipairs(QuillTrimmerMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function QuillTrimmerMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.ironCost and QuillTrimmerMaker.ironStock<(d.ironCost or 0) then return false,"Premalo železa" end; if d.bronzeCost and QuillTrimmerMaker.bronzeStock<(d.bronzeCost or 0) then return false,"Premalo brona" end; if d.woodCost and QuillTrimmerMaker.woodStock<(d.woodCost or 0) then return false,"Premalo lesa" end; if d.leatherCost and QuillTrimmerMaker.leatherStock<(d.leatherCost or 0) then return false,"Premalo usnja" end; if d.silverCost and QuillTrimmerMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and QuillTrimmerMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and QuillTrimmerMaker.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if d.pearlCost and QuillTrimmerMaker.pearlStock<(d.pearlCost or 0) then return false,"Premalo biserov" end; if #QuillTrimmerMaker.buildings==0 then return false,"Potrebna strižna delavnica" end; if not QuillTrimmerMaker.maker then return false,"Potreben strižnik" end; return true end
function QuillTrimmerMaker.make(pt,qty) qty=qty or 1; local ok,e=QuillTrimmerMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.ironCost then QuillTrimmerMaker.ironStock=QuillTrimmerMaker.ironStock-d.ironCost*qty end; if d.bronzeCost then QuillTrimmerMaker.bronzeStock=QuillTrimmerMaker.bronzeStock-d.bronzeCost*qty end; if d.woodCost then QuillTrimmerMaker.woodStock=QuillTrimmerMaker.woodStock-d.woodCost*qty end; if d.leatherCost then QuillTrimmerMaker.leatherStock=QuillTrimmerMaker.leatherStock-d.leatherCost*qty end; if d.silverCost then QuillTrimmerMaker.silverStock=QuillTrimmerMaker.silverStock-d.silverCost*qty end; if d.goldCost then QuillTrimmerMaker.goldStock=QuillTrimmerMaker.goldStock-d.goldCost*qty end; if d.jewelCost then QuillTrimmerMaker.jewelStock=QuillTrimmerMaker.jewelStock-d.jewelCost*qty end; if d.pearlCost then QuillTrimmerMaker.pearlStock=QuillTrimmerMaker.pearlStock-d.pearlCost*qty end; local t=d.time; if QuillTrimmerMaker.maker then t=math.max(1,t-math.floor(QuillTrimmerMaker.maker.skill/13)) end; table.insert(QuillTrimmerMaker.activeMaking,{id="quilltrimmer_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,food=0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function QuillTrimmerMaker.completeMaking(m) local q=1.0+(QuillTrimmerMaker.getQualityBonus()/100); if QuillTrimmerMaker.maker then q=q+(QuillTrimmerMaker.maker.skill/140) end; q=math.min(2.5,q); QuillTrimmerMaker.productStock[m.productType]=(QuillTrimmerMaker.productStock[m.productType] or 0)+m.quantity; QuillTrimmerMaker.totalProducts=QuillTrimmerMaker.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if QuillTrimmerMaker.maker then QuillTrimmerMaker.maker.itemsMade=QuillTrimmerMaker.maker.itemsMade+m.quantity; if math.random()<0.25 then QuillTrimmerMaker.maker.skill=math.min(100,QuillTrimmerMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Strižnik izdelan: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"quilltrimmer.completed",{productName=m.productName,prestige=m.prestige,happiness=m.happiness}) end end
function QuillTrimmerMaker.update(dt) if not _G.state then return end; QuillTrimmerMaker.dayTimer=QuillTrimmerMaker.dayTimer+dt; if QuillTrimmerMaker.dayTimer>=30 then QuillTrimmerMaker.dayTimer=0; for i=#QuillTrimmerMaker.activeMaking,1,-1 do local m=QuillTrimmerMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then QuillTrimmerMaker.completeMaking(m); table.remove(QuillTrimmerMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(QuillTrimmerMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if QuillTrimmerMaker.maker then tu=tu+15 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function QuillTrimmerMaker.getStats() return {ironStock=QuillTrimmerMaker.ironStock,bronzeStock=QuillTrimmerMaker.bronzeStock,woodStock=QuillTrimmerMaker.woodStock,leatherStock=QuillTrimmerMaker.leatherStock,silverStock=QuillTrimmerMaker.silverStock,goldStock=QuillTrimmerMaker.goldStock,jewelStock=QuillTrimmerMaker.jewelStock,pearlStock=QuillTrimmerMaker.pearlStock,productStock=QuillTrimmerMaker.productStock,numBuildings=#QuillTrimmerMaker.buildings,hasMaker=QuillTrimmerMaker.maker~=nil,makerName=QuillTrimmerMaker.maker and QuillTrimmerMaker.maker.name or "—",makerSkill=QuillTrimmerMaker.maker and QuillTrimmerMaker.maker.skill or 0,activeMaking=#QuillTrimmerMaker.activeMaking,totalProducts=QuillTrimmerMaker.totalProducts} end
return QuillTrimmerMaker
